   orbit.Width=form.ClientSize.Width<1100?245:310;
   workColumns.ColumnStyles[0].Width=catalogue.Parent==workColumns&&catalogue.Visible?(form.ClientSize.Width<1400?290:330)*scale:0;
   layoutRoot.RowStyles[0].Height=Math.Max(43,line+23);layoutRoot.RowStyles[2].Height=0;workDockHost.Visible=false;layoutRoot.RowStyles[3].Height=line+7;
   workDock.RowStyles[0].Height=line*2+21;
   int[] heights={0,32,34,0,54,70,36};for(int i=0;i<heights.Length;i++)if(i!=3)catalogue.RowStyles[i].Height=(solveContent!=null&&i>=4?0:heights[i])*scale;
   foreach(var entry in commandButtons.Where(x=>x.Value=="macro-insert"||x.Value=="macro-replace"))if(entry.Key.Parent!=null&&entry.Key.Parent.Parent==catalogue){entry.Key.AutoSize=false;entry.Key.Dock=DockStyle.Fill;entry.Key.Margin=new Padding(1,1,1,2);}
  }finally{catalogue.ResumeLayout(true);workDock.ResumeLayout(true);layoutRoot.ResumeLayout(true);}
