 string MacroShortName(Dictionary<string,object> m){string name=Text(m["name"]);if(name.StartsWith("O",StringComparison.Ordinal)&&name.Contains(" · retained star ")){int at=name.IndexOf(" · retained star ",StringComparison.Ordinal);name="Star "+name.Substring(at+17).Replace("inverse","reverse");}return name;}
 bool OperationExecuted {get{return Text(Value(work,"operation_state"))=="executed";}}
 void ShowOperation(bool visible){if(mode!="g2")return;if(visible)OpenWorkWindow("operation",false);else HideWorkWindow("operation");operationOpen=visible;FitWorkspace();}
 void DrawOperationState(){
  if(operationStrip==null)return;var review=Map(Value(work,"review"));var result=Map(Value(review,"goal_result"));operationNotice.Visible=OperationExecuted||result!=null;
  string status=Text(Value(result,"status"));operationNotice.Text=OperationExecuted?"Executed · steps retained":Text(Value(review,"status"))=="Stale"?"Goal · check again":status=="Met"?"Goal met · preview":status=="Unmet"?"Goal not yet met":status=="MissingInput"?"Goal · set requirement":status=="NotApplicable"?"Preparation":"Goal · unverified";
  tips.SetToolTip(operationNotice,OperationExecuted?"Retained steps are not pending again. Choose New or Reuse explicitly.":Text(Value(result,"reason"))+" Protection is checked separately.");
  foreach(var entry in commandButtons.Where(x=>!x.Key.IsDisposed&&x.Key.Parent==operationStrip)){
   if(entry.Value=="operation-new"||entry.Value=="operation-reuse")entry.Key.Visible=OperationExecuted;
   else if(entry.Value!="review-details"&&entry.Value!="cancel-analysis")entry.Key.Visible=!OperationExecuted;
  }
  foreach(var entry in commandButtons.Where(x=>!x.Key.IsDisposed&&(x.Value=="macro-insert"||x.Value=="macro-replace")))entry.Key.Enabled=!OperationExecuted;
  FitSolveWindow();
 }
 string MacroName(Dictionary<string,object> m){int o=Number(m["orbit"]);return o==Number(Value(Workspace,"orbit"))?MacroShortName(m):OrbitName(o)+" · "+MacroShortName(m);}
 string OrbitProfileDetails(int o){
  var profiles=Items(Value(structure,"orbit_profiles")).Select(Map).ToArray();var p=profiles.FirstOrDefault(x=>Number(x["orbit"])==o);if(p==null)return "Mathematical profile unavailable; canonical orbit O"+o+".";
  var lines=new List<string>();if(profiles.Count(x=>OrbitName(Number(x["orbit"]))==OrbitName(o))>1)lines.Add("This mathematical summary is shared by distinct orbits. Compare their representative cap structures; no handedness name is established.");
  lines.Add("Representative hosting cells: "+String.Join(", ",Items(Value(p,"hosting_cells")).Select(c=>"C"+c).ToArray()));
  lines.Add("Representative affecting caps: "+String.Join(", ",Items(Value(p,"affecting_caps")).Select(c=>"C"+c).ToArray()));return String.Join("\n",lines.ToArray());
 }
 string MacroDetails(Dictionary<string,object> m){
  int o=Number(m["orbit"]);var facts=Map(Value(m,"effect"));var lines=new List<string>{"Library group: O"+o+" · "+OrbitName(o),"Macro ID: "+Text(m["id"])};
  lines.Add(MacroUseDetails(m));lines.Add(MacroClassificationSummary(m));lines.Add(OrbitProfileDetails(o));lines.AddRange(Items(m["recipe"]).Select(StepDetails));
  lines.Add(facts==null?"Expanded turns: not checked. A compound star is not one physical turn.":"Expanded turns: "+facts["primitives"]+" · "+Text(facts["category"]));
  if(facts!=null){var support=Items(facts["support"]).Select(x=>"O"+Map(x)["orbit"]).ToArray();lines.Add("Exact full-model support: "+(support.Length==0?"none":String.Join(", ",support)));}
  return String.Join("\n",lines.ToArray());
 }
 void PaintMacroItem(object sender,DrawItemEventArgs e){if(e.Index<0||e.Index>=macros.Items.Count)return;var choice=(Choice)macros.Items[e.Index];var m=Items(work["library"]).Select(Map).First(x=>Text(x["id"])==choice.Id);bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Color.FromArgb(34,45,56):macros.BackColor))e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,MacroName(m),macros.Font,new Rectangle(e.Bounds.X+10,e.Bounds.Y+5,e.Bounds.Width-20,22),Ink,TextFormatFlags.EndEllipsis);using(var f=new Font("Segoe UI",9f))TextRenderer.DrawText(e.Graphics,CandidateCaption(m),f,new Rectangle(e.Bounds.X+10,e.Bounds.Y+28,e.Bounds.Width-20,20),Color.FromArgb(147,164,173),TextFormatFlags.EndEllipsis);if(selected)using(var pen=new Pen(Accent,3))e.Graphics.DrawLine(pen,e.Bounds.Left+1,e.Bounds.Top+3,e.Bounds.Left+1,e.Bounds.Bottom-3);e.DrawFocusRectangle();}
 string StepText(object item){var s=Map(item);if(s==null)return "Unknown step";if(Text(Value(s,"kind"))=="word")return String.Join(" ",Items(Value(s,"moves")).Select(Text).ToArray());if(Text(Value(s,"kind"))=="star"){int o=Number(s["orbit"]);return OrbitName(o)+" · Compound star "+Text(s["node"])+(Number(s["sign"])<0?" reverse":" forward");}return api.Json(s);}
 string StepDetails(object item){var s=Map(item);string text=StepText(item);return s!=null&&Text(Value(s,"kind"))=="star"?text+"\nCanonical star: O"+s["orbit"]+" / node "+s["node"]+" / sign "+s["sign"]:text;}
 void DrawWorkspace(){if(mode!="g2")return;foreach(var pair in lanes){var items=Items(Map(Workspace["draft"])[pair.Key]);pair.Value.Steps=items.Length==0?"Empty":String.Join("  →  ",items.Select(StepText).ToArray());pair.Value.Shortcut=KeyHint("phase-"+pair.Key);pair.Value.Chosen=Text(Workspace["phase"])==pair.Key;pair.Value.Invalidate();string laneDetails=pair.Value.PhaseName+"\n"+String.Join("\n",items.Select(StepDetails).ToArray())+"\nA row can contain a compound operation; it is not an expanded-turn index.\nDouble-click to edit; right-click to change key.";tips.SetToolTip(pair.Value,pair.Value.PhaseName+" · "+items.Length+" steps. Double-click to inspect or edit."+KeyHint("edit-"+pair.Key));pair.Value.AccessibleDescription=laneDetails;}var chosen=Items(work["library"]).Select(Map).FirstOrDefault(m=>Text(m["id"])==selectedMacro);if(chosen==null)macroState.Text=macros.Items.Count==0?MacroEmptyMessage():"Select a macro";else{int count=Items(Map(Workspace["draft"])[Text(phase)]).Length;macroState.Text=""+MacroShortName(chosen)+(macros.SelectedIndex<0?" [hidden by filters]":"")+"\n"+Text(phase)+": "+count+" steps · draft";}string detail=chosen==null?"Select a macro to inspect its exact scope.":MacroDetails(chosen);tips.SetToolTip(macros,"Select to inspect; Add inserts the chosen macro into the draft.");tips.SetToolTip(macroState,"Open Details for full effects, use-score reasons and the original recipe.");macroState.AccessibleDescription=detail;foreach(var pair in commandButtons.Where(x=>!x.Key.IsDisposed&&x.Value=="macro-insert"))pair.Key.Text="Add to "+Text(phase)+KeyHint("macro-insert");}
 void EditSteps(string name){
  if(!connected||busy||OperationExecuted){Say("Finish the current operation or explicitly start a new draft before editing steps.",true);return;}
  string originalDraft=api.Json(Map(Workspace["draft"])[name]),originalState=Text(work["hash"]);
  var draft=Items(Map(Workspace["draft"])[name]).Select(x=>api.Parse(api.Json(x))).ToList();var dialog=new Form{Text=Char.ToUpperInvariant(name[0])+name.Substring(1)+" steps",Font=form.Font,BackColor=Paper,ForeColor=Ink,ClientSize=new Size(650,400),MinimumSize=new Size(530,330),StartPosition=FormStartPosition.CenterParent};
  var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(14)};grid.RowStyles.Add(new RowStyle(SizeType.Absolute,30));grid.RowStyles.Add(new RowStyle(SizeType.Percent,100));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,35));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,42));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,44));var list=new ListBox{Dock=DockStyle.Fill,IntegralHeight=false,BorderStyle=BorderStyle.FixedSingle,AccessibleName="Ordered explicit operation steps"};var words=new TextBox{Dock=DockStyle.Fill,AccessibleName="Signed legal generators separated by spaces"};var error=new Label{Dock=DockStyle.Fill,ForeColor=Color.FromArgb(172,58,45)};grid.Controls.Add(new Label{Text="Ordered steps · changes apply only when you save",Dock=DockStyle.Fill},0,0);grid.Controls.Add(list,0,1);grid.Controls.Add(words,0,2);grid.Controls.Add(error,0,3);var buttons=Row();Action refresh=()=>{int index=list.SelectedIndex;list.Items.Clear();foreach(var s in draft)list.Items.Add(StepText(s));if(index>=0&&list.Items.Count>0)list.SelectedIndex=Math.Min(index,list.Items.Count-1);};refresh();
  Action<string,Action> add=(label,action)=>{var b=new Button{Text=label,AutoSize=true,Height=30,FlatStyle=FlatStyle.Flat};b.Click+=delegate{try{action();}catch(Exception e){error.Text=e.Message;}};buttons.Controls.Add(b);};
  add("Add turns",()=>{int[] moves=words.Text.Split(new[]{' ',',',';','\t','\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(t=>{int n;if(!Int32.TryParse(t,out n)||n==0||n< -1200||n>1200)throw new ArgumentException("Use signed generators −1200…−1 or 1…1200. Input kept.");return n;}).ToArray();if(moves.Length==0)throw new ArgumentException("Enter exact turns first, for example 1 -1.");draft.Add(LocalApi.D("kind","word","moves",moves));words.Clear();refresh();});
  add("Remove",()=>{if(list.SelectedIndex>=0){draft.RemoveAt(list.SelectedIndex);refresh();}});add("Up",()=>{int n=list.SelectedIndex;if(n>0){var x=draft[n];draft.RemoveAt(n);draft.Insert(n-1,x);refresh();list.SelectedIndex=n-1;}});add("Down",()=>{int n=list.SelectedIndex;if(n>=0&&n+1<draft.Count){var x=draft[n];draft.RemoveAt(n);draft.Insert(n+1,x);refresh();list.SelectedIndex=n+1;}});var save=new Button{Text="Save steps",AutoSize=true,Height=30,FlatStyle=FlatStyle.Flat};save.Click+=async delegate{if(busy||OperationExecuted||originalState!=Text(work["hash"])||originalDraft!=api.Json(Map(Workspace["draft"])[name])){error.Text="The operation changed while these steps were open. Your edit is kept; cancel and reopen the current draft.";return;}if(!String.IsNullOrWhiteSpace(words.Text)){error.Text="Use Add turns first, or clear the input. Your typed turns have not been saved.";words.Focus();return;}grid.Enabled=false;try{if(await Send(LocalApi.D("action","draft","phase",name,"recipe",draft.ToArray())))dialog.Close();else error.Text=feedback.Text;}catch(Exception e){error.Text=e.Message;}finally{if(!grid.IsDisposed)grid.Enabled=true;}};buttons.Controls.Add(save);var cancel=new Button{Text="Cancel",DialogResult=DialogResult.Cancel,AutoSize=true,FlatStyle=FlatStyle.Flat};buttons.Controls.Add(cancel);dialog.CancelButton=cancel;grid.Controls.Add(buttons,0,4);dialog.Controls.Add(grid);ShowOwned(dialog);dialog.Dispose();
 }
}
